def find_active_sorafs_todo_markers(paths: list[Path]) -> list[str]:
    offenders: list[str] = []
    for path in paths:
        for line_number, line in enumerate(read(path).splitlines(), start=1):
            if ACTIVE_SORAFS_TODO_MARKER_RE.search(line):
                label = active_sorafs_todo_path_label(path)
                offenders.append(f"{label}:{line_number}: {line.strip()}")
    return offenders


def test_active_sorafs_todo_marker_detection_has_negative_controls(
    tmp_path: Path,
) -> None:
    todo_prefix = "TO" "DO:"
    assert ACTIVE_SORAFS_TODO_MARKER_RE.search(f"// {todo_prefix} bypass SoraFS review")
    assert ACTIVE_SORAFS_TODO_MARKER_RE.search("# FIXME: bypass SoraFS review")
    assert ACTIVE_SORAFS_TODO_MARKER_RE.search("// XXX: bypass SoraFS review")
    assert ACTIVE_SORAFS_TODO_MARKER_RE.search("# TBD: bypass SoraFS review")
    assert ACTIVE_SORAFS_TODO_MARKER_RE.search("// todo: bypass SoraFS review")
    assert ACTIVE_SORAFS_TODO_MARKER_RE.search("# FixMe(bypass SoraFS review)")
    assert ACTIVE_SORAFS_TODO_MARKER_RE.search("// tbd - bypass SoraFS review")
    assert not ACTIVE_SORAFS_TODO_MARKER_RE.search("methodology")
    assert not ACTIVE_SORAFS_TODO_MARKER_RE.search(
        "methodology todo text is not an active marker"
    )
    assert not ACTIVE_SORAFS_TODO_MARKER_RE.search(
        "skipped: 0, todo: 0, topLevel: 46, suites: 0 });"
    )

    clean = tmp_path / "clean_sorafs.py"
    clean.write_text("notes = 'methodology todo text is not an active marker'\n")
    dirty = tmp_path / "dirty_sorafs.py"
    dirty.write_text("# todo: bypass SoraFS source review\n")

    assert find_active_sorafs_todo_markers([clean]) == []
    offenders = find_active_sorafs_todo_markers([dirty])
    assert len(offenders) == 1
    assert "todo: bypass SoraFS source review" in offenders[0]


def reviewed_sorafs_open_work_inventory() -> set[tuple[str, str]]:
    """Read the exact reviewed markers without allowing wildcard exemptions."""
    rows = ACTIVE_SORAFS_OPEN_WORK_INVENTORY.read_text().splitlines()
    assert rows.pop(0) == "path\tmarker"
    inventory = set()
    for row in rows:
        path, marker = row.split("\t", 1)
        assert path and marker and ACTIVE_SORAFS_TODO_MARKER_RE.search(marker)
        assert (path, marker) not in inventory
        inventory.add((path, marker))
    return inventory


def test_active_sorafs_todo_inventory_matches_reviewed_open_work() -> None:
    tracked_files = subprocess.check_output(
        ["git", "ls-files"], cwd=REPO_ROOT, text=True
    ).splitlines()
    observed: set[tuple[str, str]] = set()

    for relative_name in tracked_files:
        relative = Path(relative_name)
        if REPO_ROOT / relative == ACTIVE_SORAFS_OPEN_WORK_INVENTORY:
            continue
        # Dated incident and implementation history is retained evidence,
        # never a statement that the active candidate still ships that work.
        if relative.parts[:2] == ("docs", "history"):
            continue
        path = REPO_ROOT / relative
        if not path.is_file():
            continue
        try:
            lines = path.read_text(encoding="utf-8").splitlines()
        except UnicodeDecodeError:
            continue
        for line_number, line in enumerate(lines, start=1):
            if (
                not ACTIVE_SORAFS_TODO_MARKER_RE.search(line)
                or ("SoraFS" not in line and "sorafs" not in line)
            ):
                continue
            if relative == ACTIVE_SORAFS_TODO_INVENTORY_ALLOWED_RELATIVE_PATH and any(
                fragment in line
                for fragment in ACTIVE_SORAFS_TODO_INVENTORY_ALLOWED_FRAGMENTS
            ):
                continue
            observed.add((str(relative), line.strip()))

    expected = {
        (path, marker)
        for path, marker in reviewed_sorafs_open_work_inventory()
        if "SoraFS" in marker or "sorafs" in marker
    }
    assert observed == expected


def test_completed_sorafs_task_inventory_has_no_active_markers() -> None:
    inventory = REPO_ROOT / "todo_list.txt"
    marker_terms = ("to" + "do", "fix" + "me", "x" + "xx", "t" + "bd")
    terms = "|".join(marker_terms)
    marker = re.compile(
        r"(?:sorafs.*(?:" + terms + r"))|(?:(?:" + terms + r").*sorafs)",
        re.I,
    )

    assert inventory.exists()

    offenders = [
        f"{index}: {line.strip()}"
        for index, line in enumerate(read(inventory).splitlines(), start=1)
        if marker.search(line)
    ]

    assert offenders == []


