def test_active_sorafs_todo_scan_covers_sdk_sorafs_content_sources() -> None:
    scanned = {path.relative_to(REPO_ROOT) for path in active_sorafs_todo_scan_paths()}
    roots = (
        REPO_ROOT / "python" / "iroha_python" / "src",
        REPO_ROOT / "python" / "iroha_torii_client",
        REPO_ROOT / "javascript" / "iroha_js" / "src",
        REPO_ROOT / "javascript" / "iroha_js" / "index.d.ts",
        REPO_ROOT / "java" / "iroha_android" / "src" / "main" / "java",
        REPO_ROOT / "kotlin" / "core-jvm" / "src" / "main" / "java",
        REPO_ROOT / "csharp" / "src",
        REPO_ROOT / "IrohaSwift" / "Sources",
    )
    excluded_parts = {
        "build",
        "dist",
        "fixtures",
        "node_modules",
        "target",
        "test",
        "tests",
    }
    missing: list[str] = []

    for root in roots:
        paths = [root] if root.is_file() else sorted(root.rglob("*"))
        for path in paths:
            if (
                not path.is_file()
                or path.suffix not in ACTIVE_SORAFS_TODO_SCAN_SUFFIXES
            ):
                continue
            relative = path.relative_to(REPO_ROOT)
            if any(part.lower() in excluded_parts for part in relative.parts):
                continue
            source = read(path)
            if ("SoraFS" in source or "sorafs" in source) and relative not in scanned:
                missing.append(str(relative))

    assert missing == []


def test_active_sorafs_source_todos_match_reviewed_open_work() -> None:
    paths = active_sorafs_todo_scan_paths()
    observed = {
        (active_sorafs_todo_path_label(path), line.strip())
        for path in paths
        for line in read(path).splitlines()
        if ACTIVE_SORAFS_TODO_MARKER_RE.search(line)
    }
    scanned = {active_sorafs_todo_path_label(path) for path in paths}
    expected = {
        (path, marker)
        for path, marker in reviewed_sorafs_open_work_inventory()
        if path in scanned
    }
    assert observed == expected


@pytest.mark.parametrize("change", ("insert", "remove", "alter"))
def test_reviewed_sorafs_open_work_inventory_rejects_unreviewed_changes(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, change: str,
) -> None:
    source = tmp_path / "sorafs_work.rs"
    marker = "// TO" "DO: retain authenticated finalized custody before admission"
    source.write_text(marker + "\n")
    inventory = tmp_path / "open_work.tsv"
    inventory.write_text("path\tmarker\n" + str(source) + "\t" + marker + "\n")
    monkeypatch.setattr(sys.modules[__name__], "ACTIVE_SORAFS_OPEN_WORK_INVENTORY", inventory)
    monkeypatch.setattr(sys.modules[__name__], "active_sorafs_todo_scan_paths", lambda: [source])
    test_active_sorafs_source_todos_match_reviewed_open_work()
    if change == "insert":
        source.write_text(marker + "\n// TO" "DO: add an unreviewed bypass\n")
    elif change == "remove":
        source.write_text("")
    else:
        source.write_text(marker.replace("before", "after") + "\n")
    with pytest.raises(AssertionError):
        test_active_sorafs_source_todos_match_reviewed_open_work()


def test_moderation_local_snapshot_reads_have_no_empty_projection_fallback() -> None:
    api = read(TORII_SORAFS_API_RS)
    handlers = {
        name: api.split(f"pub(crate) async fn {name}", 1)[1].split(
            "\npub(crate) async fn", 1
        )[0]
        for name in (
            "handle_get_sorafs_moderation_model_registry",
            "handle_get_sorafs_moderation_screening_results",
            "handle_get_sorafs_moderation_quarantine",
            "handle_get_sorafs_moderation_quarantine_operator_panel",
            "handle_post_sorafs_moderation_quarantine_appeal_handoff",
        )
    }
    required = {
        "handle_get_sorafs_moderation_model_registry": (
            ("moderation_model_registry_read_view(limit)", "moderation_model_registry_error_response"),
        ),
        "handle_get_sorafs_moderation_screening_results": (
            ("moderation_screening_read_view(limit)", "moderation_screening_error_response"),
        ),
        "handle_get_sorafs_moderation_quarantine": (
            ("moderation_quarantine_read_view(limit)", "moderation_screening_error_response"),
        ),
        "handle_get_sorafs_moderation_quarantine_operator_panel": (
            ("moderation_quarantine_record(&quarantine_id)", "moderation_screening_error_response"),
            (
                "moderation_quarantine_object_record(&quarantine_id)",
                "moderation_quarantine_object_error_response",
            ),
        ),
        "handle_post_sorafs_moderation_quarantine_appeal_handoff": (
            ("moderation_quarantine_record(&quarantine_id)", "moderation_screening_error_response"),
        ),
    }
    for name, checks in required.items():
        for source_call, error_mapper in checks:
            assert source_call in handlers[name]
            assert f"Err(err) => return {error_mapper}(err)" in handlers[name]

    node = read(SORAFS_NODE_LIB_RS)
    for snapshot in (
        "model_registry",
        "screening",
        "quarantine_object",
        "evidence_viewer",
    ):
        assert f"pub fn moderation_{snapshot}_snapshot(" not in node


