UNSHIPPED_CLI_SDK_DISTRIBUTION_ROUTE_PATTERNS = (
    "/v1/sorafs/cli/releases",
    "/v1/sorafs/cli/distribution",
    "/v1/sorafs/cli/live-governance",
    "/v1/sorafs/cli/governance-runbooks",
    "/v1/sorafs/sdk/distribution",
    "/v1/sorafs/sdk/registries",
    "/v1/sorafs/sdk/live-deployment",
    "/v1/sorafs/release/promotion",
)

UNSHIPPED_CLI_SDK_DISTRIBUTION_CLI_SUBCOMMANDS = (
    "release-distribute",
    "release-publish",
    "distribution-publish",
    "homebrew-publish",
    "npm-publish",
    "crates-publish",
    "go-module-publish",
    "sdk-distribute",
    "live-governance-capture",
    "governance-runbook-capture",
    "release-promote",
)

UNSHIPPED_CLI_SDK_DISTRIBUTION_NESTED_CLI_COMMANDS = (
    "release distribute",
    "release publish",
    "distribution publish",
    "homebrew publish",
    "npm publish",
    "crates publish",
    "go-module publish",
    "go module publish",
    "sdk distribute",
    "live governance capture",
    "governance runbook capture",
    "release promote",
)


def unshipped_cli_sdk_distribution_route_matches(source: str) -> list[str]:
    return [
        route
        for route in UNSHIPPED_CLI_SDK_DISTRIBUTION_ROUTE_PATTERNS
        if re.search(rf"(?<![A-Za-z0-9_/-]){re.escape(route)}(?=$|[\"`/\s?}}])", source)
    ]


def unshipped_cli_sdk_distribution_cli_matches(source: str) -> list[str]:
    hyphenated_matches = [
        subcommand
        for subcommand in UNSHIPPED_CLI_SDK_DISTRIBUTION_CLI_SUBCOMMANDS
        if f'"{subcommand}"' in source or f"`{subcommand}`" in source
    ]
    nested_matches = [
        command
        for command in UNSHIPPED_CLI_SDK_DISTRIBUTION_NESTED_CLI_COMMANDS
        if re.search(rf"(?<![A-Za-z0-9_/-]){re.escape(command)}(?=$|[\"`\s])", source)
    ]
    return hyphenated_matches + nested_matches


def test_cli_sdk_distribution_surface_matcher_has_negative_controls() -> None:
    shipped_local_route_candidates = (
        "/v1/sorafs/cli/releases-canary",
        "/v1/sorafs/cli/distribution-evidence",
        "/v1/sorafs/cli/live-governance-canary",
        "/v1/sorafs/sdk/distribution-canary",
        "/v1/sorafs/sdk/registries-evidence",
        "/v1/sorafs/release/promotion-canary",
    )
    shipped_local_subcommands = (
        "sorafs",
        "iroha",
        "release_sorafs_cli",
        "check_sorafs_cli_release",
        "sorafs-gateway-self-cert",
        "sorafs-gateway-attest",
        "fixture-smoke",
        "release-distribute-canary",
        "homebrew-publish-evidence",
        "live-governance-capture-canary",
        "release-promote-canary",
        "release distribute-canary",
        "homebrew publish-evidence",
        "sdk distribute-canary",
        "live governance capture-canary",
        "release promote-canary",
    )

    assert unshipped_cli_sdk_distribution_route_matches(
        '"GET /v1/sorafs/cli/releases" '
        "`/v1/sorafs/sdk/distribution` "
        '"/v1/sorafs/release/promotion?deployment_id=prod"'
    ) == [
        "/v1/sorafs/cli/releases",
        "/v1/sorafs/sdk/distribution",
        "/v1/sorafs/release/promotion",
    ]
    assert (
        unshipped_cli_sdk_distribution_route_matches(
            " ".join(f'"{route}"' for route in shipped_local_route_candidates)
        )
        == []
    )
    assert unshipped_cli_sdk_distribution_cli_matches(
        '"release-publish" `npm-publish` "release-promote"'
    ) == [
        "release-publish",
        "npm-publish",
        "release-promote",
    ]
    assert unshipped_cli_sdk_distribution_cli_matches(
        "`iroha sorafs release distribute` "
        '"sorafs release publish" '
        "`distribution publish` "
        '"homebrew publish --registry tap" '
        "`npm publish` "
        '"crates publish" '
        "`go-module publish` "
        '"go module publish" '
        "`sdk distribute` "
        '"live governance capture --deployment prod" '
        "`governance runbook capture` "
        '"release promote --deployment prod"'
    ) == [
        "release distribute",
        "release publish",
        "distribution publish",
        "homebrew publish",
        "npm publish",
        "crates publish",
        "go-module publish",
        "go module publish",
        "sdk distribute",
        "live governance capture",
        "governance runbook capture",
        "release promote",
    ]
    assert unshipped_cli_sdk_distribution_cli_matches(
        " ".join(f'"{subcommand}"' for subcommand in shipped_local_subcommands)
    ) == []


def test_unshipped_cli_sdk_distribution_surface_is_not_exposed() -> None:
    exposed: dict[str, list[str]] = {}

    for path in (TORII_SORAFS_API_RS, TORII_OPENAPI_RS):
        source = read(path)
        matched = unshipped_cli_sdk_distribution_route_matches(source)
        if matched:
            exposed[str(path.relative_to(REPO_ROOT))] = matched

    for path in (IROHA_CLI_SORAFS_RS, SORAFS_CLI_RS):
        source = read(path)
        matched = unshipped_cli_sdk_distribution_cli_matches(source)
        if matched:
            exposed[str(path.relative_to(REPO_ROOT))] = matched

    assert exposed == {}


def test_por_live_deployment_and_archive_work_stays_open_in_docs() -> None:
    scheduler = read(SORAFS_POR_PLAN)
    validator = read(SORAFS_POR_VALIDATOR_PLAN)
    normalized_scheduler = re.sub(r"\s+", " ", scheduler)
    normalized_validator = re.sub(r"\s+", " ", validator)

    required_scheduler_open = (
        "Torii now constructs a verified randomness provider from pinned chain public-key/genesis/period metadata, at least three canonical HTTPS endpoints, a strict-majority quorum, bounded DNS/body/timeouts, freshness limits, and a durable high-water state file.",
        "`sorafs.por.enabled = true` fails startup when this configuration is missing or internally inconsistent. It also requires the complete non-secret `[sorafs.por.potr_runtime]` binding and injected `PotrRuntimeSignerRolesV1`; every configured signer, qualification, gateway key, reader/source/resolver identity, and baseline finalized admission field must match the injected roles exactly.",
        "The local SF-9 state/report integration and verified drand/provider-VRF feeds are implemented. Release promotion remains blocked on reviewed live deployment evidence and any production governance archive handoff required by the operator.",
        "Operators should keep SF-9 promotion fail-closed until the payload-free deployment evidence passes the checked-in gate:",
        "The checker recognizes `sorafs.por.*` SF-9 rollout schemas for randomness, scheduler runtime, validator replay, reporting/archive handoff, observability, and governance approval.",
        "Archive a live drand/VRF/auditor run showing deterministic challenge generation and verdict replay that passes the SF-9 rollout evidence gate",
        "operator-required governance archive handoff carried as `governance_archive_handoff_digest_hex`",
    )
    required_validator_open = (
        "Remaining SF-9b work is live auditor rollout evidence, production archive handoff, and any richer proof-bundle inspection commands required by operators.",
        "The SF-9 validator/reporting release claim is tied to the same fail-closed gate used by the scheduler plan:",
        "The validator-specific evidence must prove `iroha app sorafs toolkit validate por` challenge/proof replay, challenge/proof binding, exact sample coverage, deadline policy, Merkle/archive replay, `ValidationOutcomeV1` schema compatibility, bounded status/export/report route latency, weekly report generation, archive-retention policy, governance archive handoff, and the exact `archive_backend` value (`sql` or `parquet`).",
        "Add proof-bundle fetch/show/offline replay commands if operators need them beyond `iroha app sorafs toolkit validate por`.",
        "Archive live auditor, drand, VRF, report, and export evidence before treating SF-9 as fully released, and require that evidence to pass the SF-9 gate.",
    )
    missing_scheduler = [
        phrase
        for phrase in required_scheduler_open
        if phrase not in normalized_scheduler
    ]
    missing_validator = [
        phrase for phrase in required_validator_open if phrase not in normalized_validator
    ]

    assert missing_scheduler == []
    assert missing_validator == []


