SHIPPED_PDP_PROVIDER_ROUTES = (
    "/v1/sorafs/pdp/challenge",
    "/v1/sorafs/pdp/next",
    "/v1/sorafs/pdp/proof",
    "/v1/sorafs/pdp/status",
    "/v1/sorafs/pdp/export",
)

RESERVED_PDP_PROVIDER_ROUTE_PATTERNS = (
    "/v1/sorafs/pdp/provider-transport",
    "/v1/sorafs/pdp/proof-generation",
    "/v1/sorafs/pdp/provider-signatures",
    "/v1/sorafs/pdp/inclusion-witnesses",
    "/v1/sorafs/pdp/governance-archive",
    "/v1/sorafs/pdp/repair-handoff",
    "/v1/sorafs/pdp/operator-cli",
    "/v1/sorafs/pdp/promotion",
)

RESERVED_PDP_PROVIDER_CLI_SUBCOMMANDS = (
    "pdp-challenge",
    "pdp-fetch",
    "pdp-respond",
    "pdp-verify",
    "pdp-status",
    "pdp-export",
    "pdp-provider-transport",
    "pdp-proof-generation",
    "pdp-governance-archive",
    "pdp-repair-handoff",
    "pdp-promote",
)

RESERVED_PDP_PROVIDER_NESTED_CLI_COMMANDS = (
    "pdp challenge",
    "pdp fetch",
    "pdp respond",
    "pdp verify",
    "pdp status",
    "pdp export",
    "pdp provider-transport",
    "pdp proof-generation",
    "pdp governance-archive",
    "pdp repair-handoff",
    "pdp promote",
)


def reserved_pdp_provider_route_matches(source: str) -> list[str]:
    return [
        route
        for route in RESERVED_PDP_PROVIDER_ROUTE_PATTERNS
        if re.search(rf"(?<![A-Za-z0-9_/-]){re.escape(route)}(?=$|[\"`/\s?}}])", source)
    ]


def reserved_pdp_provider_cli_matches(source: str) -> list[str]:
    hyphenated = [
        subcommand
        for subcommand in RESERVED_PDP_PROVIDER_CLI_SUBCOMMANDS
        if f'"{subcommand}"' in source or f"`{subcommand}`" in source
    ]
    nested = [
        command
        for command in RESERVED_PDP_PROVIDER_NESTED_CLI_COMMANDS
        if re.search(
            rf"(?<![A-Za-z0-9_/-]){re.escape(command)}(?=$|[\"`\s])",
            source,
        )
    ]
    return [*hyphenated, *nested]


def test_reserved_pdp_provider_surface_matcher_has_negative_controls() -> None:
    shipped_local_routes = (
        "/v1/sorafs/proof/stream",
        "/v1/sorafs/proof/stream?proof_kind=pdp",
    )
    shipped_local_route_candidates = (
        "/v1/sorafs/pdp/provider-transport-canary",
        "/v1/sorafs/pdp/proof-generation-evidence",
        "/v1/sorafs/pdp/governance-archive-canary",
        "/v1/sorafs/pdp/repair-handoff-evidence",
        "/v1/sorafs/pdp/promotion-canary",
    )
    shipped_local_subcommands = (
        "proof",
        "stream",
        "proof stream --proof-kind=pdp",
        "sorafs_cli",
        "iroha",
        "pdp",
        "pdp-rollout",
        "pdp-provider-transport-canary",
        "pdp-proof-generation-canary",
        "pdp-governance-archive-canary",
    )

    assert reserved_pdp_provider_route_matches(
        '"POST /sorafs/pdp/challenge" '
        "`/v1/sorafs/pdp/proof` "
        '"/v1/sorafs/pdp/promotion?deployment_id=prod"'
    ) == [
        "/v1/sorafs/pdp/promotion",
    ]
    assert (
        reserved_pdp_provider_route_matches(
            '"/v1/sorafs/pdp/challenge" "/v1/sorafs/pdp/proof"'
        )
        == []
    )
    assert (
        reserved_pdp_provider_route_matches(
            " ".join(f'"{route}"' for route in shipped_local_routes)
        )
        == []
    )
    assert (
        reserved_pdp_provider_route_matches(
            " ".join(f'"{route}"' for route in shipped_local_route_candidates)
        )
        == []
    )
    assert reserved_pdp_provider_cli_matches(
        '"pdp-challenge" `pdp-proof-generation` "pdp-promote"'
    ) == [
        "pdp-challenge",
        "pdp-proof-generation",
        "pdp-promote",
    ]
    assert reserved_pdp_provider_cli_matches(
        "`sorafs pdp challenge` "
        '"sorafs pdp fetch" '
        "`pdp respond` "
        '"pdp verify" '
        "`pdp status` "
        '"pdp export"'
    ) == [
        "pdp challenge",
        "pdp fetch",
        "pdp respond",
        "pdp verify",
        "pdp status",
        "pdp export",
    ]
    assert reserved_pdp_provider_cli_matches(
        " ".join(f'"{subcommand}"' for subcommand in shipped_local_subcommands)
    ) == []


def test_pdp_provider_protocol_exposes_only_the_canonical_v1_api_family() -> None:
    api = read(TORII_SORAFS_API_RS)
    openapi = read(TORII_OPENAPI_RS)
    torii = read(TORII_LIB_RS)

    for route in SHIPPED_PDP_PROVIDER_ROUTES:
        assert f'"{route}"' in openapi
    for handler in (
        "handle_post_sorafs_pdp_challenge",
        "handle_post_sorafs_pdp_next",
        "handle_post_sorafs_pdp_proof",
        "handle_post_sorafs_pdp_status",
        "handle_post_sorafs_pdp_export",
    ):
        assert f"fn {handler}(" in api
        assert f"sorafs::api::{handler}" in torii

    exposed: dict[str, list[str]] = {}
    for path in (TORII_SORAFS_API_RS, TORII_OPENAPI_RS):
        source = read(path)
        matched = reserved_pdp_provider_route_matches(source)
        if matched:
            exposed[str(path.relative_to(REPO_ROOT))] = matched

    for path in (IROHA_CLI_SORAFS_RS, SORAFS_CLI_RS):
        source = read(path)
        matched = reserved_pdp_provider_cli_matches(source)
        if matched:
            exposed[str(path.relative_to(REPO_ROOT))] = matched

    assert exposed == {}


def test_governance_dag_publication_service_is_documented_as_shipped() -> None:
    source = read(SORAFS_GOVERNANCE_DAG_PLAN)
    service = governance_service_source(SORAFS_GOVERNANCE_DAG_SERVICE_RS)

    outstanding_start = source.index("Still outstanding:")
    outstanding_end = source.index("\n## Goals & Scope", outstanding_start)
    normalized_outstanding = re.sub(
        r"\s+", " ", source[outstanding_start:outstanding_end]
    )
    required_shipped = (
        "The `sorafs_governance_dag` service implementation, exposed through the public `run_governance_dag_service` library launcher, is the always-on production service",
        "uploads and recursively pins every new block plus the signed head",
        "authenticated HTTP compare-and-swap or IPNS resolve/publish/",
        "A service-specific authenticated checkpoint and write-ahead publish intent",
        "bounded public mirror, head, block, node, checkpoint, health, and Prometheus surface",
        "The standard outbound path already consumes verified nonces through separate sealed IPFS and signed-head slots",
        "receiver-side sealed cross-replica replay adapter",
    )
    normalized_source = re.sub(r"\s+", " ", source)
    assert [phrase for phrase in required_shipped if phrase not in normalized_source] == []
    assert "reconciled SF-12 rollout gate" in normalized_outstanding
    assert "RocksDB/IPLD backend only if" in normalized_outstanding
    assert "Reconcile the rollout checker" not in normalized_outstanding

    for marker in (
        "async fn ipfs_add_verified(",
        "async fn ipfs_pin(",
        "async fn ipfs_verify_pin(",
        "async fn ipfs_cat(",
        "async fn put_signed_http_head(",
        "async fn fetch_signed_http_head(",
        "GovernanceDagSealedCheckpointStore",
        "GovernanceDagSealedStateSlot::PublishIntent",
        "GovernanceDagSealedStateSlot::IpfsRequestReplay",
        "GovernanceDagSealedStateSlot::SignedHeadRequestReplay",
        "consume_sealed_request_auth_nonce",
        "run_governance_dag_service",
        '"/v1/sorafs/governance/dag/checkpoint"',
        "sorafs_governance_dag_ipfs_pin_lag_seconds",
        "real_kubo_publication_signed_head_restart_and_tamper_lane",
    ):
        assert marker in service


