UNSHIPPED_ORDERBOOK_SERVICE_ROUTE_PATTERNS = (
    "/v1/sorafs/orderbook/contract",
    "/v1/sorafs/orderbook/contracts",
    "/v1/sorafs/orderbook/matcher-service",
    "/v1/sorafs/orderbook/settlement-service",
    "/v1/sorafs/orderbook/escrow-custody",
    "/v1/sorafs/orderbook/dashboard",
    "/v1/sorafs/orderbook/contract-stream",
)

UNSHIPPED_ORDERBOOK_SERVICE_CLI_SUBCOMMANDS = (
    "match-daemon",
    "matcher-service",
    "settlement-daemon",
    "contract-submit",
    "contract-forward",
    "escrow-mutate",
    "dashboard-serve",
)

UNSHIPPED_ORDERBOOK_SERVICE_NESTED_CLI_COMMANDS = (
    "orderbook match-daemon",
    "orderbook matcher-service",
    "orderbook settlement-daemon",
    "orderbook contract-submit",
    "orderbook contract-forward",
    "orderbook escrow-mutate",
    "orderbook dashboard-serve",
)


def unshipped_orderbook_service_route_matches(source: str) -> list[str]:
    return [
        route
        for route in UNSHIPPED_ORDERBOOK_SERVICE_ROUTE_PATTERNS
        if re.search(rf"(?<![A-Za-z0-9_/-]){re.escape(route)}(?=$|[\"`/\s?}}])", source)
    ]


def unshipped_orderbook_service_cli_matches(source: str) -> list[str]:
    hyphenated_matches = [
        subcommand
        for subcommand in UNSHIPPED_ORDERBOOK_SERVICE_CLI_SUBCOMMANDS
        if f'"{subcommand}"' in source or f"`{subcommand}`" in source
    ]
    nested_matches = [
        command
        for command in UNSHIPPED_ORDERBOOK_SERVICE_NESTED_CLI_COMMANDS
        if re.search(rf"(?<![A-Za-z0-9_/-]){re.escape(command)}(?=$|[\"`\s])", source)
    ]
    return hyphenated_matches + nested_matches


def test_orderbook_service_surface_matcher_has_negative_controls() -> None:
    shipped_local_routes = (
        "/v1/sorafs/orderbook/orders",
        "/v1/sorafs/orderbook/cancel",
        "/v1/sorafs/orderbook/receipts",
        "/v1/sorafs/orderbook/book",
        "/v1/sorafs/orderbook/trades",
        "/v1/sorafs/orderbook/channels",
        "/v1/sorafs/orderbook/events",
        "/v1/sorafs/orderbook/events/stream",
        "/v1/sorafs/orderbook/events/ws",
    )
    shipped_local_route_candidates = (
        "/v1/sorafs/orderbook/contract-canary",
        "/v1/sorafs/orderbook/contracts-evidence",
        "/v1/sorafs/orderbook/matcher-service-canary",
        "/v1/sorafs/orderbook/settlement-service-evidence",
        "/v1/sorafs/orderbook/contract-stream-canary",
        "/v1/sorafs/orderbook/dashboard-local",
    )
    shipped_local_subcommands = (
        "orders",
        "cancel",
        "receipts",
        "book",
        "trades",
        "channels",
        "events",
        "events-stream",
        "events-ws",
        "validate",
        "orderbook-canary",
        "contract-submit-canary",
        "dashboard-serve-canary",
        "orderbook orders",
        "orderbook cancel",
        "orderbook receipts",
        "orderbook book",
        "orderbook trades",
        "orderbook channels",
        "orderbook events",
        "orderbook events-stream",
        "orderbook events-ws",
        "orderbook contract-submit-canary",
        "orderbook dashboard-serve-canary",
    )

    assert unshipped_orderbook_service_route_matches(
        '"POST /v1/sorafs/orderbook/contract/submit" '
        "`/v1/sorafs/orderbook/matcher-service` "
        '"/v1/sorafs/orderbook/dashboard?deployment_id=prod"'
    ) == [
        "/v1/sorafs/orderbook/contract",
        "/v1/sorafs/orderbook/matcher-service",
        "/v1/sorafs/orderbook/dashboard",
    ]
    assert unshipped_orderbook_service_route_matches(
        '"/v1/sorafs/orderbook/contracts" '
        '"/v1/sorafs/orderbook/contract-stream"'
    ) == [
        "/v1/sorafs/orderbook/contracts",
        "/v1/sorafs/orderbook/contract-stream",
    ]
    assert (
        unshipped_orderbook_service_route_matches(
            " ".join(f'"{route}"' for route in shipped_local_routes)
        )
        == []
    )
    assert (
        unshipped_orderbook_service_route_matches(
            " ".join(f'"{route}"' for route in shipped_local_route_candidates)
        )
        == []
    )
    assert unshipped_orderbook_service_cli_matches(
        '"match-daemon" `contract-submit` "dashboard-serve"'
    ) == [
        "match-daemon",
        "contract-submit",
        "dashboard-serve",
    ]
    assert unshipped_orderbook_service_cli_matches(
        "`sorafs orderbook matcher-service` "
        '"sorafs orderbook settlement-daemon" '
        "`orderbook contract-submit` "
        '"orderbook dashboard-serve --listen :8080"'
    ) == [
        "orderbook matcher-service",
        "orderbook settlement-daemon",
        "orderbook contract-submit",
        "orderbook dashboard-serve",
    ]
    assert unshipped_orderbook_service_cli_matches(
        " ".join(f'"{subcommand}"' for subcommand in shipped_local_subcommands)
    ) == []


def test_unshipped_orderbook_service_surface_is_not_exposed() -> None:
    exposed: dict[str, list[str]] = {}
    for path in (TORII_SORAFS_API_RS, TORII_OPENAPI_RS):
        source = read(path)
        matched = unshipped_orderbook_service_route_matches(source)
        if matched:
            exposed[str(path.relative_to(REPO_ROOT))] = matched
    cli_source = read(SORAFS_CLI_RS)
    matched_commands = unshipped_orderbook_service_cli_matches(cli_source)
    if matched_commands:
        exposed[str(SORAFS_CLI_RS.relative_to(REPO_ROOT))] = matched_commands
    assert exposed == {}

def test_hedging_billing_cli_binds_exact_checkpoint_responses_before_output() -> None:
    cli = read_iroha_cli_sorafs_with_tests()
    response = read(IROHA_CLI_SORAFS_RS.parent / "sorafs" / "hedging_billing_response.rs")
    response_tests = read(IROHA_CLI_SORAFS_RS.parent / "sorafs" / "hedging_billing_response_tests.rs")
    assert "mod hedging_billing_response;" in cli and cli.count("hedging_billing_response::render(") == 2
    render_position = response.index("context.print_data(&value)")
    assert all(response.index(marker) < render_position for marker in ('get_all("content-type")', 'Some("application/json")', "values.next().is_none()", "if status != StatusCode::OK", "norito::json::from_slice", 'anchor.get("checkpoint_fingerprint")', "expected_checkpoint.to_ascii_uppercase()"))
    hedging_test_markers = ("billing_statements_cli_rejects_missing_response_anchor_without_output", "hedging_projection_cli_rejects_mismatched_and_wrong_case_anchors_without_output", "exact_checkpoint_cli_rejects_ambiguous_json_media_type_without_output", "exact_checkpoint_cli_rejects_non_ok_without_echoing_response")
    assert all(marker in response_tests for marker in hedging_test_markers)
    # The CLI unit-test module must actually include the response tests.
    assert all(marker in cli for marker in hedging_test_markers)

def test_hedging_runtime_docs_distinguish_shipped_core_from_external_deployment() -> None:
    source = read(SORAFS_HEDGING_PLAN)
    normalized = re.sub(r"\s+", " ", source)
    required_shipped = (
        "The separate `sorafs_node::hedging_billing_service` and supervised `irohad::sorafs_hedging_billing_runtime` now implement the local committed service pipeline.",
        "interfaces ingest contiguous typed event pages and authenticated period closes.",
        "The durable projector deterministically derives open accruals, per-account governed statements, aggregate XOR exposure, and never-automatic hedge intents",
        "reconciles ambiguous publications and authoritative acknowledgements",
        "`iroha_config` contains only the public policy path/digest, bounded work cadence, private state directory, and each adapter's opaque handle, non-zero revision, and public-policy digest",
        "missing, test-marked, unready, substituted, stale, or identity-drifting dependencies fail before durable state opens",
        "No worker or timer accepts a hedge-execution adapter.",
        "Every generated intent sets `automatic_execution=false`",
        "private-key-free external signer/publisher interfaces",
        "payload-free health/alert metrics",
        "The pre-release embedded economics authority has been hard-cut.",
        "`sorafs_node` does not admit or query an independent governed-pricing series or signed-feed ledger",
        "The `sorafs_economics_operator` role is retired.",
        "The non-secret `hedging_feed_trust_policy_path` remains only as a configuration-pinned input to the committed hedging/billing runtime",
        "Development state created by the retired implementation is deliberately not migrated.",
        "The five pre-release local economics routes are retired and must return 404; there are no aliases or compatibility handlers.",
        "Torii now mounts exactly this V1 family:",
        "`GET /v1/sorafs/billing/status`",
        "`GET /v1/sorafs/billing/statements/{statement_id}`",
        "`POST /v1/sorafs/billing/statements/{statement_id}/acknowledgements`",
        "`GET /v1/sorafs/billing/reconciliation`",
        "`GET /v1/sorafs/hedging/exposure`",
        "`GET /v1/sorafs/hedging/intents`",
        "Every route requires canonical account authentication",
        "Authenticated `GET /v1/sorafs/billing/status` is the bootstrap-anchor route:",
        "it is not gated by the `sorafs_billing_manager` role",
        "Every catalogued `GET` route also accepts its implicit authenticated `HEAD` request.",
        "required non-zero client `request_nonce` plus the bounded `authentication_proof`.",
        "proof bytes are deliberately excluded from their own preimage.",
        "`[u8; 32]` use exactly 64 uppercase hexadecimal characters",
        "Runtime status can report `ready=true` only when its latest successful tick remains inside the fixed freshness window and the projection contains a non-zero finalized cursor and height",
        "The family exposes no feed-ingestion, automatic-execution, or local-authority mutation route.",
    )
    required_external = (
        "This is not yet a complete production hedging and billing stack",
        "There is still no price-feed collector, concrete production finalized-query/journal-verifier adapter, independently administered external software signer, immutable publication service, acknowledgement authority, sealed epoch-witness store",
        "Price feed collectors | Fetch primary/secondary/tertiary feeds and normalize them into signed price payloads. | Not shipped for SoraFS hedging.",
        "These source boundaries do not supply live market feeds or concrete production implementations of the finalized query, journal verifier, signer, publisher, acknowledgement authority, sealed witness store, or governed venue adapter.",
        "Those independently administered providers, software-key custody, and deployment evidence remain external release inputs.",
        "Automated hedge execution must remain off until governance approves venues",
        "Production scrapes, alert routing, and response evidence remain open.",
        "Remaining: run focused Rust verification; deploy the live feed collector and genuine finalized-query, journal-verifier, external software signer, immutable publisher",
    )
    stale_unshipped_core_claims = (
        "daemon, exposure tracking, collector automation, and hedge execution are not shipped",
        "event ingestion and accrual service are not shipped",
        "Statement publisher | Store, sign, publish, notify, and track acknowledgements for statements. | Not shipped.",
        "Remaining: implement collector service, daemonized pricing/exposure engine, billing aggregator, statement publisher",
        "The minimum authenticated local economics operator routes described above are shipped.",
        "The embedded `sorafs_node` runtime now supplies that local governed boundary.",
        "complete public SoraFS hedging/billing API",
        "ship signed public exposure/billing/statement APIs",
    )
    missing_shipped = [phrase for phrase in required_shipped if phrase not in normalized]
    missing_external = [phrase for phrase in required_external if phrase not in normalized]
    stale_present = [
        phrase for phrase in stale_unshipped_core_claims if phrase in normalized
    ]
    assert missing_shipped == []
    assert missing_external == []
    assert stale_present == []

def test_hedging_docs_keep_rollout_contract_markers() -> None:
    required_current = (
        "The checker exports its required top-level payload fields as `EVIDENCE_REQUIRED_FIELDS`",
        "the collection planner dry-run JSON includes the checker-backed `evidence_contract` map for selected required kinds",
        "Production promotion remains blocked unless the summary status is `ready`, including at least two distinct staged billing cycles whose reference-decision ids match a valid reference-price artifact in the same evidence bundle.",
        "Feed-collector and reference-price artifacts also bind `feed_count` to the unique canonical `feeds[].name` inventory, require `accepted_feed_count` to equal `feed_count`, require coverage for the reviewed `feed-primary`, `feed-secondary`, and `feed-tertiary` price feeds, and reject duplicate or unknown feed entries before promotion can report ready.",
        "Billing-cycle artifacts also require `cycle_id` to match a reviewed lowercase `billing-cycle-*` label without non-production markers, bind `statement_count` to the unique canonical `statements[].name` inventory using reviewed `billing-statement-*` labels without non-production markers, and bind `line_item_count` to the unique canonical `line_items[].name` inventory using reviewed `billing-line-item-*` labels without non-production markers, rejecting duplicate statement or line-item entries before promotion can report ready.",
        "The aggregate production-readiness gate now derives cycle tuple and policy digest sets from `valid_billing_cycles`: `valid_cycle_bindings` must match those cycle tuples, `valid_policy_digests` must match those cycle policies, and every billing-cycle `reference_decision_id_hex` must appear in `valid_reference_decision_ids` before final promotion can report ready. It also rechecks cycle-bound and policy-bound artifact fingerprints against `valid_cycle_bindings` and `valid_policy_digests`.",
        "The hedging gate fail-closes when more than one valid cycle tuple or policy anchor appears, and clears the mixed `valid_cycle_bindings` or `valid_policy_digests` set before aggregate promotion can report ready.",
        "Statement-publication artifacts also bind `route_count` to the unique canonical `routes[].name` inventory and reject duplicate or unknown route entries before promotion can report ready, require every route response to carry a lowercase `body_blake3_hex` digest, and bind `acknowledgement_probe_count` to the unique canonical `acknowledgement_probes` inventory using reviewed `billing-ack-probe-*` labels without non-production markers.",
        "Statement-publication canaries bind `acknowledgement_probe_count` to reviewed `billing-ack-probe-*` `acknowledgement_probes` inventory and reject duplicate or non-production acknowledgement probes.",
        "Reconciliation artifacts also bind `source_count` to the unique canonical `sources[].name` inventory and `line_item_count` to the unique canonical `line_items[].name` inventory using reviewed `billing-line-item-*` labels without non-production markers, rejecting duplicate or unknown source entries and duplicate line-item entries before promotion can report ready.",
        "Native-bridge release artifacts also bind `artifact_count` to the unique canonical `artifacts[].id` inventory, require reviewed `hedging-native-artifact-*` labels without non-production markers, and reject duplicate artifact entries before promotion can report ready.",
        "They also require artifact IDs to start with reviewed native bridge family prefixes and at least one Swift-family plus one JNI-family artifact before promotion can report ready",
        "Hedging/billing payload-safety artifacts must explicitly set `payload_bytes_included`, `response_bodies_included`, `degraded`, `statement_bodies_included`, `raw_financial_records_included`, `critical_alerts_firing`, and `debug_artifacts` to `false` before promotion can report ready.",
        "Metrics/alert artifacts also bind `metric_count` to the unique canonical `metrics` inventory and reject duplicate or unknown metric entries before promotion can report ready.",
        "The summary exports the sorted reviewed `metrics` inventory plus `metric_count_values`, and the aggregate production-readiness gate requires those fields to match the metrics/alert artifact fingerprint before final promotion can report ready.",
        "The runner validates the schema-closed collection-plan envelope before printing dry-run JSON or executing the verifier.",
    )
    missing_current: dict[str, list[str]] = {}
    for path in (SORAFS_HEDGING_PLAN,):
        source = read(path)
        normalized = re.sub(r"\s+", " ", source)
        missing = [phrase for phrase in required_current if phrase not in normalized]
        if missing:
            missing_current[str(path.relative_to(REPO_ROOT))] = missing
    assert missing_current == {}
    checker = read(SCRIPTS_DIR / "check_sorafs_hedging_rollout_evidence.py")
    checker_test = read(SCRIPTS_DIR / "tests" / "check_sorafs_hedging_rollout_evidence_test.py")
    builder = read(SCRIPTS_DIR / "build_sorafs_hedging_canary.py")
    builder_test = read(SCRIPTS_DIR / "tests" / "build_sorafs_hedging_canary_test.py")
    aggregate_checker = read(SCRIPTS_DIR / "check_sorafs_production_readiness.py")
