def unshipped_gateway_compliance_route_matches(source: str) -> list[str]:
    return [
        route
        for route in UNSHIPPED_GATEWAY_COMPLIANCE_ROUTE_PATTERNS
        if re.search(rf"(?<![A-Za-z0-9_/-]){re.escape(route)}(?=$|[\"`/\s?}}])", source)
    ]


def unshipped_gateway_compliance_cli_matches(source: str) -> list[str]:
    hyphenated_matches = [
        subcommand
        for subcommand in UNSHIPPED_GATEWAY_COMPLIANCE_CLI_SUBCOMMANDS
        if f'"{subcommand}"' in source or f"`{subcommand}`" in source
    ]
    nested_matches = [
        command
        for command in UNSHIPPED_GATEWAY_COMPLIANCE_NESTED_CLI_COMMANDS
        if re.search(rf"(?<![A-Za-z0-9_/-]){re.escape(command)}(?=$|[\"`\s])", source)
    ]
    return hyphenated_matches + nested_matches


def test_gateway_fixture_d1_is_governed_compliance_refusal() -> None:
    fixture_dir = REPO_ROOT / "fixtures" / "sorafs_gateway" / "1.0.0"
    scenarios = json.loads(read(fixture_dir / "scenarios.json"))
    policy_matrix = json.loads(read(fixture_dir / "policy_matrix.json"))
    scenario = next(entry for entry in scenarios if entry["id"] == "D1")
    policy = next(entry for entry in policy_matrix if entry["id"] == "D1")

    assert scenario == {
        "id": "D1",
        "description": "Load denied by governed gateway compliance",
        "expected_status": 451,
        "expected_outcome": "refusal",
    }
    assert policy == {
        "id": "D1",
        "description": "Load denied by governed gateway compliance",
        "status": 451,
        "error": "gateway_compliance_denied",
        "policy": "gateway_compliance",
    }
    fixture_source = read(
        REPO_ROOT / "xtask" / "src" / "sorafs" / "gateway_fixture.rs"
    )
    assert "Load denied by governed gateway compliance" in fixture_source
    assert "Load with GAR denylist trigger" not in fixture_source


def test_gateway_compliance_service_surface_matcher_has_negative_controls() -> None:
    shipped_local_routes = (
        "/v1/sorafs/transparency/tokens",
        "/v1/sorafs/transparency/tokens/verify",
        "/v1/sorafs/moderation/quarantine/{quarantine_id_hex}/appeal-handoff",
    )
    shipped_local_route_candidates = (
        "/v1/sorafs/gateway/compliance/controller-canary",
        "/v1/sorafs/gateway/compliance/moderation-toggle-canary",
        "/v1/sorafs/gateway/compliance/appeal-overrides-canary",
        "/v1/sorafs/gateway/compliance/feed-sync-proof",
        "/v1/sorafs/gateway/compliance/promotion-canary",
    )
    shipped_local_subcommands = (
        "honey-audit",
        "gateway-compliance-canary",
        "controller-canary",
        "moderation-toggle-canary",
        "appeal-override-canary",
        "feed-sync-proof",
        "promotion-canary",
        "gateway compliance canary",
        "gateway compliance controller-canary",
        "gateway compliance moderation-toggle-canary",
        "gateway compliance appeal-override-canary",
        "gateway compliance feed-sync-proof",
        "gateway compliance promotion-canary",
        "gar proof-token",
        "transparency publication-canary",
    )

    assert unshipped_gateway_compliance_route_matches(
        '"GET /v1/sorafs/gateway/compliance/controller/status" '
        "`/v1/sorafs/gateway/compliance/moderation-toggle` "
        '"/v1/sorafs/gateway/compliance/promotion?deployment_id=prod"'
    ) == [
        "/v1/sorafs/gateway/compliance/controller",
        "/v1/sorafs/gateway/compliance/moderation-toggle",
        "/v1/sorafs/gateway/compliance/promotion",
    ]
    assert (
        unshipped_gateway_compliance_route_matches(
            " ".join(f'"{route}"' for route in shipped_local_routes)
        )
        == []
    )
    assert (
        unshipped_gateway_compliance_route_matches(
            " ".join(f'"{route}"' for route in shipped_local_route_candidates)
        )
        == []
    )
    assert unshipped_gateway_compliance_cli_matches(
        '"compliance-controller" `moderation-toggle-service` "gateway-compliance-promote"'
    ) == [
        "compliance-controller",
        "moderation-toggle-service",
        "gateway-compliance-promote",
    ]
    assert unshipped_gateway_compliance_cli_matches(
        "`iroha sorafs gateway compliance controller` "
        '"sorafs gateway compliance moderation toggle" '
        "`gateway compliance feed-sync` "
        '"gateway compliance promote --deployment prod"'
    ) == [
        "compliance controller",
        "compliance moderation toggle",
        "compliance feed-sync",
        "compliance promote",
    ]
    assert unshipped_gateway_compliance_cli_matches(
        " ".join(f'"{subcommand}"' for subcommand in shipped_local_subcommands)
    ) == []


def test_unshipped_gateway_compliance_service_surface_is_not_exposed() -> None:
    exposed: dict[str, list[str]] = {}

    for path in (TORII_SORAFS_API_RS, TORII_OPENAPI_RS):
        source = read(path)
        matched = unshipped_gateway_compliance_route_matches(source)
        if matched:
            exposed[str(path.relative_to(REPO_ROOT))] = matched

    for path in (IROHA_CLI_SORAFS_RS, SORAFS_CLI_RS):
        source = read(path)
        matched = unshipped_gateway_compliance_cli_matches(source)
        if matched:
            exposed[str(path.relative_to(REPO_ROOT))] = matched

    assert exposed == {}


def test_gateway_compliance_control_surface_is_single_canonical_authenticated_family() -> None:
    route_catalog = read(TORII_ROUTE_CATALOG_RS)
    torii = read(TORII_LIB_RS)
    openapi = read(TORII_OPENAPI_RS)
    control = read(TORII_SORAFS_GATEWAY_COMPLIANCE_API_RS)
    serving = read(TORII_SORAFS_API_RS)

    for route in SHIPPED_GATEWAY_COMPLIANCE_ROUTES:
        assert f'"{route}"' in route_catalog
        assert f'"{route}"' in openapi

    required_handlers = (
        "handle_get_sorafs_gateway_compliance_feed",
        "handle_get_sorafs_gateway_compliance_status",
        "handle_post_sorafs_gateway_compliance_stage",
        "handle_post_sorafs_gateway_compliance_acknowledge",
        "handle_post_sorafs_gateway_compliance_promote",
        "handle_post_sorafs_gateway_compliance_rollback",
    )
    for handler in required_handlers:
        assert handler in torii
        assert handler in control

    assert control.count("verify_canonical_network_request(") == 1
    assert "sorafs_gateway_compliance_operator" in control
    assert "require_exact_canonical_json" in control
    assert "MAX_GATEWAY_COMPLIANCE_CATALOG_BYTES_V1" in control
    assert "current_unix_second()" in control
    assert "evaluate_serving(kind, subject, observed_at_unix)" in serving
    assert "GatewayComplianceSubjectKindV1::ManifestDigest" in serving
    assert "GatewayComplianceSubjectKindV1::Cid" in serving
    assert "GatewayComplianceSubjectKindV1::Provider" in serving
    assert "gateway_compliance_unavailable_response()" in serving


def test_gateway_load_rollout_evidence_work_stays_open_in_docs() -> None:
    source = read(SORAFS_GATEWAY_LOAD_PLAN)
    normalized = re.sub(r"\s+", " ", source)

    required_open = (
        "It does not open a live gateway or sleep through a wall-clock soak test",
        "HTTP/3 is explicitly non-applicable to V1 and is not a readiness dependency.",
        "Live staging load evidence",
        "V1 has no committed SoraFS HTTP/3 endpoint or release requirement. Any later transport work is separately scoped and cannot block or satisfy V1 readiness.",
        "Archive signed local conformance reports from `ci/check_sorafs_gateway_conformance.sh`",
        "Run a live staging load rig with the same fixture bundle",
        "Add a live-target adapter if operators need the integration test to exercise a deployed gateway instead of the fixture-backed adapter.",
        "Record cold-cache SLO baselines after the staging hardware profile is chosen.",
        "A later HTTP/3 transport project is outside this V1 plan.",
        "`scripts/check_sorafs_gateway_load_rollout_evidence.py` validates payload-free local conformance, live staging load, telemetry/SLO, transport-scope, and governance approval evidence before SF-5a load promotion.",
        "`scripts/run_sorafs_gateway_load_rollout_evidence.py` emits the matching collection plan and dry-run evidence contract",
        "runner validates the schema-closed collection plan, required kinds, thresholds, external evidence map, evidence contract, and command steps before dry-run output or verifier execution.",
        "Staging-load artifacts must also keep `stream_count` and `provider_count` equal to the unique canonical `streams[].name` and `providers[].name` inventories, must contain at least two distinct providers, and reject duplicate stream or provider entries before promotion can report ready.",
        "Stream labels must use generated `gateway-load-stream-0000`-style names",
        "Staging-load artifacts reject placeholder or malformed `gateway_version` labels before promotion can report ready, reject the retired `cache_state` field and every unknown or extra top-level/nested field, require `providers[].name` entries to use reviewed `gateway-load-provider-*` labels, require `hardware_profile.name` to use reviewed `gateway-load-hardware-*` labels, and reject placeholder or test markers in provider and hardware-profile labels before promotion can report ready.",
        "Local-conformance artifacts also bind `scenario_count` to the unique canonical `scenarios` inventory, require the reviewed gateway-load scenarios, and reject duplicate or unknown scenario labels before promotion can report ready.",
        "Telemetry/SLO artifacts also bind `metric_count` to the unique canonical `metrics` inventory, require the reviewed gateway-load metrics, and reject duplicate or unknown metric labels before promotion can report ready.",
        "Gateway-load payload-safety artifacts must explicitly set `raw_report_included`, `private_keys_included`, `response_bodies_included`, `raw_payloads_included`, and `critical_alerts_firing` to `false`; transport-scope artifacts must also explicitly bind the V1 HTTP/3 non-applicability state: `http3_endpoint_committed`, `http3_config_surface_documented`, and `http3_scenarios_passed` are `false`, while `http3_scenarios_deferred` is `true`.",
        "The summary exports the sorted reviewed `metrics` inventory plus `metric_count_values`, and the aggregate production-readiness gate requires those fields to match the telemetry/SLO artifact fingerprint before final promotion can report ready.",
        "Aggregate promotion also rechecks the lane-proven digest relationships: suite-bound artifact fingerprints must match `valid_suite_report_digests`, staging-bound artifact fingerprints must match `valid_staging_report_digests`, and policy-bound artifact fingerprints must match `valid_policy_digests`.",
        "Gateway-load rollout summaries must expose exactly one active local conformance suite digest, one active staging-load report digest, and one active policy digest; mixed valid anchors fail closed before final promotion can report ready.",
    )
    missing = [phrase for phrase in required_open if phrase not in normalized]

    assert missing == []


